namespace Finance.Domain.Common;

/// <summary>
/// Base class for every entity that belongs to a user and takes part in offline sync.
/// </summary>
public abstract class UserOwnedEntity : IHasTimestamps
{
    /// <summary>UUID v7, generated by the client.</summary>
    public Guid Id { get; set; }

    public Guid UserId { get; set; }

    public DateTime CreatedAt { get; set; }

    public DateTime UpdatedAt { get; set; }

    /// <summary>Assigned by the server from the global sequence on every change; drives sync pull.</summary>
    public long Version { get; set; }

    public DateTime? DeletedAt { get; set; }

    public bool IsDeleted => DeletedAt is not null;

    public void MarkDeleted(DateTime utcNow) => DeletedAt ??= utcNow;
}
